std::random_device rd;
    std::mt19937 gen(rd());
    std::normal_distribution<double> dist(0.0, 1.0);

    const double kB = 1.380649e-23; // Boltzmann constant
    vec3 com_velocity(0.0, 0.0, 0.0);
    double total_mass = 0.0;

    // Initialize velocities from Maxwell-Boltzmann distribution
    for (std::size_t i = 0; i < velocities.size(); ++i) {
        double mass = masses[i];
        double std_dev = std::sqrt(kB * temperature / mass);

        velocities[i].x = dist(gen) * std_dev;
        velocities[i].y = dist(gen) * std_dev;
        velocities[i].z = dist(gen) * std_dev;

        com_velocity += velocities[i] * mass;
        total_mass += mass;
    }

    // Remove center of mass motion
    if (total_mass > 0.0) {
        com_velocity /= total_mass;
        for (auto& v : velocities) {
            v -= com_velocity;
        }
    }
    // END_CODE

